from pathlib import Path
root=Path('app/src/main/assets')
html=root/'index.html'
s=html.read_text()
marker='</body>'
assert s.count(marker)==1
s=s.replace(marker,'<script src="navigation-5.9.8.js"></script>\n'+marker)
html.write_text(s.replace('5.9.7','5.9.8'))
(root/'navigation-5.9.8.js').write_text("/* ASPLAYER 5.9.8: stable D-pad focus and category reveal. */\n(function(){\n'use strict';\nconst focusable='button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex=\"-1\"])';\nconst state=new Map();\nlet lastKeyAt=0;\nconst style=document.createElement('style');\nstyle.textContent='.asplayer-598-focused:focus{outline:3px solid #f8d873!important;outline-offset:3px!important;scroll-margin:72px!important}';\ndocument.head.appendChild(style);\nfunction visible(el){\n if(!el||!el.isConnected||el.closest('.hidden,[hidden],[aria-hidden=\"true\"]'))return false;\n const s=getComputedStyle(el),r=el.getBoundingClientRect();\n return s.display!=='none'&&s.visibility!=='hidden'&&r.width>3&&r.height>3;\n}\nfunction scope(){\n return [...document.querySelectorAll('.modal:not(.hidden),.playeroverlay:not(.hidden)')].pop()||\n document.querySelector('.login-page:not(.hidden)')||document.querySelector('main')||document.body;\n}\nfunction candidates(){\n const root=scope();\n return [...root.querySelectorAll(focusable)].filter(visible);\n}\nfunction move(key){\n const items=candidates();if(!items.length)return false;\n const a=document.activeElement;\n if(!items.includes(a)){\n   const saved=state.get(scope());\n   const first=saved&&items.includes(saved)?saved:items[0];\n   first.focus({preventScroll:true});first.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'});return true;\n }\n const r=a.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2;\n const horizontal=key==='ArrowLeft'||key==='ArrowRight',sign=(key==='ArrowRight'||key==='ArrowDown')?1:-1;\n let best=null,bestScore=Infinity;\n for(const el of items){\n   if(el===a)continue;\n   const b=el.getBoundingClientRect(),dx=b.left+b.width/2-x,dy=b.top+b.height/2-y;\n   const forward=(horizontal?dx:dy)*sign,side=Math.abs(horizontal?dy:dx);\n   if(forward<=4)continue;\n   const primarySize=horizontal?(r.width+b.width)/2:(r.height+b.height)/2;\n   const crossSize=horizontal?(r.height+b.height)/2:(r.width+b.width)/2;\n   const score=Math.max(0,forward-primarySize)+Math.max(0,side-crossSize)*4+side*.3;\n   if(score<bestScore){best=el;bestScore=score;}\n }\n if(!best)return false;\n best.focus({preventScroll:true});\n best.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'});\n return true;\n}\n// Window capture precedes the legacy document capture handler; consume only handled arrows.\nwindow.addEventListener('keydown',e=>{\n if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)||e.altKey||e.ctrlKey||e.metaKey)return;\n const a=document.activeElement;\n if(a?.isContentEditable||a?.matches('input:not([type=button]),textarea,select,[role=combobox],[role=slider]'))return;\n const now=performance.now();\n if(e.repeat&&now-lastKeyAt<85){e.preventDefault();e.stopImmediatePropagation();return;}\n if(move(e.key)){lastKeyAt=now;e.preventDefault();e.stopImmediatePropagation();}\n},true);\ndocument.addEventListener('focusin',e=>{\n const el=e.target;if(!el.matches?.(focusable))return;\n document.querySelectorAll('.asplayer-598-focused').forEach(n=>n.classList.remove('asplayer-598-focused'));\n el.classList.add('asplayer-598-focused');state.set(scope(),el);\n});\n// Reveal the refreshed results when the category selector changes, without assuming a fixed DOM layout.\nfunction isCategory(el){\n const s=((el.id||'')+' '+(el.className||'')+' '+(el.getAttribute('aria-label')||'')+' '+(el.closest('[class*=categor],[id*=categor]')?.className||'')).toLowerCase();\n return /categor|genre|group/.test(s);\n}\nfunction reveal(){\n const root=scope();\n const selectors=['[id*=content]:not(.hidden) [class*=card]','[class*=results]:not(.hidden) [class*=card]','[class*=grid]:not(.hidden) [class*=card]','[class*=list]:not(.hidden) [class*=item]'];\n const target=selectors.flatMap(q=>[...root.querySelectorAll(q)]).find(visible);\n if(target)target.scrollIntoView({block:'start',inline:'nearest',behavior:'smooth'});\n}\ndocument.addEventListener('click',e=>{\n const el=e.target.closest?.('button,[role=button],a,select,[class*=categor],[id*=categor]');\n if(!el||!isCategory(el))return;\n requestAnimationFrame(()=>requestAnimationFrame(reveal));\n},false);\ndocument.addEventListener('change',e=>{\n if(isCategory(e.target))requestAnimationFrame(()=>requestAnimationFrame(reveal));\n},false);\n})();")
gradle=Path('app/build.gradle')
g=gradle.read_text()
assert 'versionCode 5907' in g
gradle.write_text(g.replace('versionCode 5907','versionCode 5908').replace('5.9.7','5.9.8'))
for p in [root/'features-5.9.3.js']:
 s=p.read_text()
 p.write_text(s.replace('5.9.7','5.9.8'))
# Preserve stored user preference, but use adaptive for a fresh installation.
p=root/'features-5.7.1.js'
s=p.read_text()
s=s.replace("bufferProfile:'normal'","bufferProfile:'adaptive'")
s=s.replace('bufferProfile: "normal"','bufferProfile: "adaptive"')
p.write_text(s)
print('ASPLAYER 5.9.8 navigation patch applied')
